// AI-generated Bystander video (Seedance 2.5, scenario 95–185 s, 89 s), 1440 × 1440, shown as a 140° view.
//
// The video frame is treated as an equirectangular patch that spans 140° × 140° around the viewer.
// · Screen (window.SI_DELIVERY = 'screen'): a magic window, "140° wrap, shows 85 %". A normal perspective view whose
//   horizontal angle is 85 % of the patch's width (2 × 0.85 × 70° = 119°); the vertical angle follows from the
//   window's shape, which is kept between 3:4 and 16:10. Drag or the arrow keys look around, only as far as the
//   picture goes (corners included), so nothing outside the picture ever shows.
// · Headset (window.SI_DELIVERY = 'headset', "VR140"): the same magic window as a preview, and Enter VR (WebXR,
//   immersive-vr, monoscopic, 'local' reference space): the patch surrounds the viewer, centred on the direction
//   they face when the session starts, with black everywhere else. The controller trigger plays or pauses.
// The video is stored encrypted: a random content key encrypts the video (AES-256-GCM), and that key is itself
// encrypted with the key derived from the study password (PBKDF2-SHA-256, the same salt and rounds as the other
// protected sessions). Nothing readable sits on the server.

const SALT = 'Ermju/gB3rbmZtE/7vFo2g==', ITER = 310000;
const BASE = new URL('./', import.meta.url).href;
// The video is split in two parts (GitHub's web upload takes at most 25 MB per file); each part is sealed separately.
const VIDEO_PARTS = ['bystander-95-185-v2.part1.enc', 'bystander-95-185-v2.part2.enc'], KEY_FILE = 'content-key.enc';
const KEEP = 'si-world-access';
const DELIVERY = window.SI_DELIVERY === 'headset' ? 'headset' : 'screen';

// The view. These numbers are fixed for the website.
const D2R = Math.PI / 180;
const WRAP = 140 * D2R;                     // the frame spans 140° around the viewer (and 140° × height / width vertically)
const SHOWS = 0.85;                         // the screen shows 85 % of that width at once; the rest is reached by looking around
const MAX_ASPECT = 1.6, MIN_ASPECT = 0.75;  // the screen view is at most 16:10 and at least 3:4
const SCREEN_BG = [0.02, 0.031, 0.051], VR_BG = [0, 0, 0];

const $ = (id) => document.getElementById(id);
const form = $('gate'), pw = $('pw'), btn = $('open'), status = $('status');
const NOT_ONLINE = 'The video is not online yet. Please try again later.';

function b64(s) { const b = atob(s), u = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) u[i] = b.charCodeAt(i); return u; }
function say(t, err) { status.textContent = t; status.className = 'status' + (err ? ' err' : ''); }

// ---------------------------------------------------------------- password gate

async function passwordKey(pass) {
    const raw = await crypto.subtle.importKey('raw', new TextEncoder().encode(pass), 'PBKDF2', false, ['deriveKey']);
    return crypto.subtle.deriveKey({ name: 'PBKDF2', salt: b64(SALT), iterations: ITER, hash: 'SHA-256' }, raw, { name: 'AES-GCM', length: 256 }, false, ['decrypt']);
}
function gcmOpen(key, buf) { return crypto.subtle.decrypt({ name: 'AES-GCM', iv: new Uint8Array(buf, 0, 12) }, key, new Uint8Array(buf, 12)); }

async function fetchWithProgress(url, onProgress) {
    const res = await fetch(url, { cache: 'force-cache' });
    if (!res.ok) throw new Error('missing');
    const total = +res.headers.get('content-length') || 0;
    if (!res.body || !res.body.getReader) return res.arrayBuffer();
    const reader = res.body.getReader(), chunks = []; let got = 0;
    for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(value); got += value.length;
        if (total) onProgress(Math.min(0.99, got / total));
    }
    const out = new Uint8Array(got); let o = 0;
    for (const c of chunks) { out.set(c, o); o += c.length; }
    return out.buffer;
}

async function unlock(pass) {
    btn.disabled = true; say('Opening the session…');
    try {
        if (!window.crypto || !crypto.subtle) throw new Error('This browser can’t open protected sessions. Use a current Chrome, Edge, Safari, Firefox or Meta Quest Browser.');
        const pk = await passwordKey(pass);
        let raw;
        try {
            const res = await fetch(BASE + KEY_FILE, { cache: 'no-cache' });
            if (!res.ok) throw new Error('missing');
            raw = await gcmOpen(pk, await res.arrayBuffer());
        } catch (e) {
            if (String(e && e.message) === 'missing') throw new Error(NOT_ONLINE);
            try { sessionStorage.removeItem(KEEP); } catch (e2) {}
            say('That password didn’t work. Check it and try again.', true); btn.disabled = false; pw.select(); return;
        }
        try { sessionStorage.setItem(KEEP, pass); } catch (e) {}
        const ck = await crypto.subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['decrypt']);
        const parts = [];
        for (let i = 0; i < VIDEO_PARTS.length; i++) {
            let enc;
            try {
                enc = await fetchWithProgress(BASE + VIDEO_PARTS[i], (f) => say('Loading the video… ' + Math.round(100 * (i + f) / VIDEO_PARTS.length) + '%'));
            } catch (e) {
                throw new Error(String(e && e.message) === 'missing' ? NOT_ONLINE : 'The video could not be loaded. Check the connection and try again.');
            }
            try { parts.push(await gcmOpen(ck, enc)); } catch (e) { throw new Error('The video could not be opened. Reload the page and try again.'); }
        }
        say('Opening the video…');
        startPlayer(URL.createObjectURL(new Blob(parts, { type: 'video/mp4' })));
    } catch (e) {
        say(String(e && e.message || e), true); btn.disabled = false;
    }
}

// ---------------------------------------------------------------- the view (WebGL)
// Each pixel's view ray is turned into longitude/latitude and looked up in the 140° patch, so the screen view is an
// exact perspective view (as in the MW140 review viewer) and, in VR, the patch sits at infinity around the viewer.

const stage = $('stage'), viewEl = $('view'), canvas = $('canvas');
const video = document.createElement('video');
video.playsInline = true; video.setAttribute('playsinline', ''); video.preload = 'auto';

const gl = canvas.getContext('webgl', { alpha: false, antialias: false, depth: false, premultipliedAlpha: false, xrCompatible: DELIVERY === 'headset' });
const VS = 'attribute vec2 p; varying vec2 ndc; void main() { ndc = p; gl_Position = vec4(p, 0.0, 1.0); }';
const FS = `precision highp float;
varying vec2 ndc;
uniform sampler2D tex;
uniform mat3 rays;   // (ndc.x, ndc.y, 1) → view ray in the picture's frame: −Z is the picture's centre, +Y is up
uniform vec2 span;   // the picture's angular width and height (radians)
uniform vec3 bg;     // colour outside the picture
uniform float ready;
void main() {
    vec3 r = normalize(rays * vec3(ndc, 1.0));
    float lon = atan(r.x, -r.z), lat = asin(clamp(r.y, -1.0, 1.0));
    vec2 uv = vec2(lon / span.x + 0.5, lat / span.y + 0.5);
    if (ready < 0.5 || uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) { gl_FragColor = vec4(bg, 1.0); return; }
    gl_FragColor = vec4(texture2D(tex, uv).rgb, 1.0);
}`;
const U = {};
let tex = null, hasFrame = false, dirty = true;

function initGL() {
    const sh = (type, src) => {
        const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s);
        if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s));
        return s;
    };
    const prog = gl.createProgram();
    gl.attachShader(prog, sh(gl.VERTEX_SHADER, VS)); gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, FS));
    gl.bindAttribLocation(prog, 0, 'p'); gl.linkProgram(prog); gl.useProgram(prog);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    ['tex', 'rays', 'span', 'bg', 'ready'].forEach((n) => { U[n] = gl.getUniformLocation(prog, n); });
    tex = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
    hasFrame = false; dirty = true;
}
if (gl) {
    initGL();
    canvas.addEventListener('webglcontextlost', (e) => { e.preventDefault(); });
    canvas.addEventListener('webglcontextrestored', initGL);
}

function refreshTexture() {
    // A new frame while playing, or once after loading or seeking.
    if ((video.paused && hasFrame && !dirty) || video.readyState < 2) return;
    try { gl.bindTexture(gl.TEXTURE_2D, tex); gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, video); hasFrame = true; dirty = false; }
    catch (e) { note('This browser could not draw the video.'); }
}
function spans() { return [WRAP, WRAP * (video.videoHeight || 1) / (video.videoWidth || 1)]; }
// 3 × 3 matrices, row-major.
const mul3 = (a, b) => { const o = []; for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) o.push(a[3 * i] * b[j] + a[3 * i + 1] * b[3 + j] + a[3 * i + 2] * b[6 + j]); return o; };
const rotX = (a) => { const c = Math.cos(a), s = Math.sin(a); return [1, 0, 0, 0, c, -s, 0, s, c]; };
const rotY = (a) => { const c = Math.cos(a), s = Math.sin(a); return [c, 0, s, 0, 1, 0, -s, 0, c]; };
function draw(rays, bg) {
    gl.uniformMatrix3fv(U.rays, false, [rays[0], rays[3], rays[6], rays[1], rays[4], rays[7], rays[2], rays[5], rays[8]]);
    gl.uniform2fv(U.span, spans()); gl.uniform3fv(U.bg, bg); gl.uniform1f(U.ready, hasFrame ? 1 : 0); gl.uniform1i(U.tex, 0);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
}

// ---------------------------------------------------------------- magic window on screen (and the headset preview)

let yaw = 0, pitch = 0;   // yaw > 0 looks left, pitch > 0 looks up
function geom() {
    const aspect = canvas.clientWidth / Math.max(1, canvas.clientHeight);
    const [hSpan, vSpan] = spans();
    const halfH = SHOWS * hSpan / 2;                 // half of the horizontal view angle: 0.85 × 70° = 59.5°
    const tanH = Math.tan(halfH), tanV = tanH / aspect, halfV = Math.atan(tanV);
    return { aspect, hSpan, vSpan, halfH, halfV, tanH, tanV };
}
// Longitude/latitude of points along the edge of the view, looking straight ahead (yaw 0) at the given pitch.
function edgeRays(g, p) {
    const out = [], n = 8, cp = Math.cos(p), sp = Math.sin(p);
    for (let i = 0; i <= n; i++) {
        const a = -1 + 2 * i / n;
        for (const [x, y] of [[a, 1], [a, -1], [1, a], [-1, a]]) {
            const rx = x * g.tanH, ry0 = y * g.tanV, len = Math.hypot(rx, ry0, 1);
            const ry = (ry0 * cp + sp) / len, rz = (ry0 * sp - cp) / len;   // pitch about X applied to (rx, ry0, −1)
            out.push([Math.atan2(rx / len, -rz), Math.asin(Math.max(-1, Math.min(1, ry)))]);
        }
    }
    return out;
}
// Keep the view on the picture: you can look around only as far as the picture goes, corners included.
function clampLook(g) {
    const latOK = (p) => edgeRays(g, p).every(([lo, la]) => Math.abs(la) <= g.vSpan / 2 + 1e-6 && Math.abs(lo) <= g.hSpan / 2 + 1e-6);
    let pm = 0;
    if (latOK(0)) { let lo = 0, hi = g.vSpan / 2; for (let i = 0; i < 18; i++) { const mid = (lo + hi) / 2; if (latOK(mid)) lo = mid; else hi = mid; } pm = lo; }
    pitch = Math.max(-pm, Math.min(pm, pitch));
    const maxLon = Math.max(...edgeRays(g, pitch).map(([lo]) => Math.abs(lo)));
    const ym = Math.max(0, g.hSpan / 2 - maxLon);
    yaw = Math.max(-ym, Math.min(ym, yaw));
}
function layout() {
    // At most 16:10, so the sides of a very wide window don't get stretched; at least 3:4, so a tall window
    // doesn't reach past the top and bottom of the picture.
    const sw = viewEl.clientWidth, sh = viewEl.clientHeight;
    const cw = Math.min(sw, Math.round(sh * MAX_ASPECT)), ch = Math.min(sh, Math.round(cw / MIN_ASPECT));
    canvas.style.width = cw + 'px'; canvas.style.height = ch + 'px';
    canvas.style.left = Math.round((sw - cw) / 2) + 'px'; canvas.style.top = Math.round((sh - ch) / 2) + 'px';
    const dpr = Math.min(window.devicePixelRatio || 1, 2), w = Math.max(1, Math.round(cw * dpr)), h = Math.max(1, Math.round(ch * dpr));
    if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
}
let raf = 0;
function screenFrame() {
    raf = requestAnimationFrame(screenFrame);
    if (gl.isContextLost()) return;
    layout(); refreshTexture();
    const g = geom(); clampLook(g);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, canvas.width, canvas.height);
    draw(mul3(rotY(yaw), mul3(rotX(pitch), [g.tanH, 0, 0, 0, g.tanV, 0, 0, 0, -1])), SCREEN_BG);
}

// ---------------------------------------------------------------- player controls

const playBtn = $('play'), muteBtn = $('mute'), vrBtn = $('vr'), over = $('overlay'), overBtn = $('overlay-btn');
let noteTimer = 0;
function note(t) { const m = $('msg'); m.textContent = t; m.hidden = !t; clearTimeout(noteTimer); if (t) noteTimer = setTimeout(() => { m.hidden = true; }, 6000); }
function fmt(t) { t = Math.max(0, Math.floor(t || 0)); return Math.floor(t / 60) + ':' + String(t % 60).padStart(2, '0'); }
function showOverlay(label) { if (xr.session) return; overBtn.textContent = label; over.hidden = false; }
function tryPlay() { video.play().catch(() => { playBtn.textContent = 'Play'; showOverlay('Play'); }); }
function toggle() { if (video.paused || video.ended) tryPlay(); else video.pause(); }

playBtn.addEventListener('click', toggle);
$('restart').addEventListener('click', () => { video.currentTime = 0; tryPlay(); });
muteBtn.addEventListener('click', () => { video.muted = !video.muted; muteBtn.textContent = video.muted ? 'Sound on' : 'Mute'; });
$('centre').addEventListener('click', () => { yaw = 0; pitch = 0; });
overBtn.addEventListener('click', () => { over.hidden = true; if (video.ended) video.currentTime = 0; tryPlay(); });
// After a mouse click, give the keyboard back to the view (Space plays or pauses, the arrows look around).
stage.querySelectorAll('button').forEach((b) => b.addEventListener('click', (e) => { if (e.detail) b.blur(); }));
video.addEventListener('loadeddata', () => { dirty = true; });
video.addEventListener('seeked', () => { dirty = true; });
video.addEventListener('play', () => { playBtn.textContent = 'Pause'; over.hidden = true; });
video.addEventListener('pause', () => { playBtn.textContent = 'Play'; });
video.addEventListener('ended', () => showOverlay('Watch again'));
const showTime = () => { $('time').textContent = fmt(video.currentTime) + ' / ' + fmt(video.duration); $('progress').style.width = (100 * video.currentTime / (video.duration || 1)) + '%'; };
video.addEventListener('timeupdate', showTime); video.addEventListener('loadedmetadata', showTime);
video.addEventListener('error', () => {
    if (!video.getAttribute('src')) return;
    if (xr.session) xr.session.end().catch(() => {});
    cancelAnimationFrame(raf);
    say('This browser could not play the video. Try a current Chrome, Edge, Safari or Meta Quest Browser.', true);
    $('access').hidden = false; stage.hidden = true; btn.disabled = false;
});

// Look around: drag (mouse, touch or pen) or the arrow keys.
let dragging = false, lx = 0, ly = 0;
canvas.addEventListener('pointerdown', (e) => { dragging = true; lx = e.clientX; ly = e.clientY; canvas.setPointerCapture(e.pointerId); });
canvas.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const k = 2 * geom().halfV / Math.max(1, canvas.clientHeight);   // the picture follows the pointer
    yaw += (e.clientX - lx) * k; pitch += (e.clientY - ly) * k; lx = e.clientX; ly = e.clientY;
});
const endDrag = () => { dragging = false; };
canvas.addEventListener('pointerup', endDrag); canvas.addEventListener('pointercancel', endDrag);
window.addEventListener('keydown', (e) => {
    const t = e.target;
    if (stage.hidden || (t && /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
    const s = 0.05;
    switch (e.key) {
        case 'ArrowLeft': yaw += s; break;
        case 'ArrowRight': yaw -= s; break;
        case 'ArrowUp': pitch += s; break;
        case 'ArrowDown': pitch -= s; break;
        case ' ': if (t && t.tagName === 'BUTTON') return; toggle(); break;
        default: return;
    }
    e.preventDefault();
});

// ---------------------------------------------------------------- VR140 (WebXR headset)

const xr = { session: null, space: null, centre: null, starting: false };
// Yaw of the direction a pose faces (> 0 is to the left of −Z), from its orientation quaternion.
function facing(q) {
    const bx = 2 * (q.w * q.y + q.x * q.z), bz = 1 - 2 * (q.x * q.x + q.y * q.y);   // −forward, forward = q · (0, 0, −1)
    if (Math.hypot(bx, bz) > 0.2) return Math.atan2(bx, bz);
    return Math.atan2(2 * (q.w * q.y - q.x * q.z), 1 - 2 * (q.y * q.y + q.z * q.z));   // looking straight up or down: use the right-hand direction
}
// View ray for NDC (x, y, 1) in the reference space: the eye's rotation × its (possibly asymmetric) frustum.
function viewRays(view) {
    const m = view.transform.matrix, p = view.projectionMatrix;
    const rot = [m[0], m[4], m[8], m[1], m[5], m[9], m[2], m[6], m[10]];
    const frustum = [1 / p[0], 0, p[8] / p[0], 0, 1 / p[5], p[9] / p[5], 0, 0, -1];
    return mul3(rot, frustum);
}
function xrFrame(t, frame) {
    const session = frame.session;
    session.requestAnimationFrame(xrFrame);
    const layer = session.renderState.baseLayer, pose = xr.space ? frame.getViewerPose(xr.space) : null;
    gl.bindFramebuffer(gl.FRAMEBUFFER, layer.framebuffer);
    gl.clearColor(0, 0, 0, 1); gl.clear(gl.COLOR_BUFFER_BIT);
    if (!pose) return;
    if (xr.centre == null) xr.centre = facing(pose.transform.orientation);   // the picture's centre: where the viewer faces at entry
    refreshTexture();
    const turn = rotY(-xr.centre);
    for (const view of pose.views) {
        const vp = layer.getViewport(view);
        if (!vp || !vp.width || !vp.height) continue;
        gl.viewport(vp.x, vp.y, vp.width, vp.height);
        draw(mul3(turn, viewRays(view)), VR_BG);   // mono: both eyes see the same picture, at infinity
    }
}
async function startXR(session) {
    xr.session = session; xr.centre = null;
    cancelAnimationFrame(raf);   // the session's frames draw from now on
    session.addEventListener('end', () => {
        xr.session = null; xr.space = null; vrBtn.textContent = 'Enter VR';
        gl.bindFramebuffer(gl.FRAMEBUFFER, null);
        cancelAnimationFrame(raf); if (!stage.hidden) raf = requestAnimationFrame(screenFrame);
    });
    session.addEventListener('select', toggle);   // controller trigger (or pinch): play or pause
    try {
        if (gl.makeXRCompatible) await gl.makeXRCompatible();
        session.updateRenderState({ baseLayer: new XRWebGLLayer(session, gl, { antialias: false }) });
        xr.space = await session.requestReferenceSpace('local');
        xr.space.addEventListener('reset', () => { xr.centre = null; });   // recentred: face the picture again
    } catch (e) {
        note('VR could not start in this browser.'); session.end().catch(() => {}); return;
    }
    vrBtn.textContent = 'Leave VR'; over.hidden = true;
    session.requestAnimationFrame(xrFrame);
    tryPlay();
}
let vrReady = false;
function setupVR() {
    if (vrReady) return;
    vrReady = true;
    const unavailable = () => { vrBtn.textContent = 'VR not available in this browser'; vrBtn.disabled = true; };
    if (!navigator.xr || !window.XRWebGLLayer) { unavailable(); return; }
    navigator.xr.isSessionSupported('immersive-vr').then((ok) => {
        if (!ok) { unavailable(); return; }
        vrBtn.disabled = false; vrBtn.textContent = 'Enter VR';
    }, unavailable);
    vrBtn.addEventListener('click', () => {
        if (xr.session) { xr.session.end().catch(() => {}); return; }
        if (xr.starting) return;
        xr.starting = true;
        navigator.xr.requestSession('immersive-vr')   // 'local' is always available in immersive sessions
            .then(startXR)
            .catch(() => note('VR could not start. Check that the headset is ready and try again.'))
            .finally(() => { xr.starting = false; });
    });
}

// ---------------------------------------------------------------- player

let videoUrl = null;
function startPlayer(src) {
    $('access').hidden = true; stage.hidden = false; say('');
    if (videoUrl) URL.revokeObjectURL(videoUrl);
    videoUrl = src; hasFrame = false; dirty = true;
    video.src = src; video.load();
    cancelAnimationFrame(raf); raf = requestAnimationFrame(screenFrame);
    if (DELIVERY === 'headset') setupVR();   // the preview waits: Enter VR (or Play) starts the video
    else tryPlay();
}

// ---------------------------------------------------------------- start

form.addEventListener('submit', (e) => { e.preventDefault(); if (pw.value) unlock(pw.value); });
(async () => {
    const closeGate = (lead) => { form.querySelectorAll('label, .row').forEach((el) => { el.hidden = true; }); $('access-lead').textContent = lead; };
    if (!gl) { closeGate('This browser can’t draw the video view (WebGL is off or unavailable). Use a current Chrome, Edge, Safari, Firefox or Meta Quest Browser.'); return; }
    // Until the locked video is uploaded, say so instead of asking for the password.
    let online = true;
    try {
        const heads = await Promise.all([KEY_FILE, ...VIDEO_PARTS].map((n) => fetch(BASE + n, { method: 'HEAD', cache: 'no-cache' })));
        online = heads.every((r) => r.ok);
    } catch (e) {}
    if (!online) { closeGate('The AI-generated video will open here with the study password once it has been uploaded.'); return; }
    let kept = null; try { kept = sessionStorage.getItem(KEEP); } catch (e) {}
    if (kept) unlock(kept); else pw.focus();
})();
